const snippets={"Python": ["from heapq import heappush, heappop", "", "class MedianFinder:", "", "    def __init__(self):", "        self.minq = []", "        self.maxq = []", "", "    def addNum(self, num: int) -> None:", "        heappush(self.maxq, -num)", "        moved = -heappop(self.maxq)", "        heappush(self.minq, moved)", "        if len(self.minq) - len(self.maxq) > 1:", "            heappush(self.maxq, -heappop(self.minq))", "", "    def findMedian(self) -> float:", "        if len(self.minq) == len(self.maxq):", "            return (self.minq[0] - self.maxq[0]) / 2", "        return self.minq[0]"], "Java": ["import java.util.*;", "class MedianFinder {", "    private PriorityQueue<Integer> minQ = new PriorityQueue<>();", "    private PriorityQueue<Integer> maxQ = new PriorityQueue<>(Collections.reverseOrder());", "", "    public MedianFinder() {", "    }", "", "    public void addNum(int num) {", "        maxQ.offer(num);", "        minQ.offer(maxQ.poll());", "        if (minQ.size() - maxQ.size() > 1) {", "            maxQ.offer(minQ.poll());", "        }", "    }", "", "    public double findMedian() {", "        return minQ.size() == maxQ.size() ? (minQ.peek() + maxQ.peek()) / 2.0 : minQ.peek();", "    }", "}"]};
